const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE_KEY='chronicleGuardians.v2.4',OLD_KEY='chronicleGuardians.v1';
let save={version:2,cards:{},records:{},settings:{mute:false,musicVolume:70},legacyBests:{}};let storageOK=true;
function validSave(v){if(!v||![1,2].includes(v.version)||!v.cards)throw Error('このゲームの記録ファイルではありません。');let out={...v,version:2,cards:{},records:{},settings:{mute:!!v.settings?.mute,musicVolume:Number.isFinite(v.settings?.musicVolume)?Math.max(0,Math.min(100,v.settings.musicVolume)):70},legacyBests:v.version===1?(v.bests||{}):(v.legacyBests||{})};for(const c of GAME_DATA.cards){const n=v.cards[c.id];if(Number.isInteger(n)&&n>0&&n<1e7)out.cards[c.id]=n;}for(const era of GAME_DATA.eras){const b=v.records?.[era.id];if(!b)continue;out.records[era.id]={};for(const k of ['time','score','accuracy','knowledge','combo','round','bosses','plays'])if(Number.isFinite(b[k])&&b[k]>=0)out.records[era.id][k]=b[k];}return extend24Save(out,v);}
save=extend24Save(save);
try{let raw=localStorage.getItem(SAVE_KEY)||localStorage.getItem('chronicleGuardians.v2')||localStorage.getItem(OLD_KEY);if(raw)save=validSave(JSON.parse(raw));localStorage.setItem(SAVE_KEY,JSON.stringify(save));}catch(e){storageOK=false;}
function persist(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(save));storageOK=true;}catch(e){storageOK=false;}storageNotice();}
function storageNotice(){$('#storageWarning').hidden=storageOK;$('#storageWarning').textContent='自動保存を利用できません。遊んだ後は、カード図鑑から記録をバックアップしてください。';$('#saveStatus').textContent=storageOK?'このブラウザに自動保存中。端末やファイルの場所を変える前に、記録をバックアップしよう。旧版のバックアップも読み込めます。':'自動保存できない環境です。画面を閉じる前に記録をバックアップしてください。';}
