function fmt(n){return Math.round(n).toLocaleString('ja-JP');}
function formatTime(s){return Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function grade(v,cuts=[90,75,50]){return v>=cuts[0]?'S':v>=cuts[1]?'A':v>=cuts[2]?'B':'C';}
const audioSys=createAudioSystem(()=>({mute:save.settings.mute,paused:currentScreen==='battle'&&!!game?.paused}),muted=>{save.settings.mute=muted;persist();renderMute();});
audioSys.musicLevel=.30*save.settings.musicVolume/100;
