function portrait(c){return `<img src="${ART[c.id]}" alt="${c.name}の創作イラスト" draggable="false">`;}
function rarityName(c){return c.ultra?'ULTRA RARE':['','COMMON','UNCOMMON','RARE','SUPER RARE','LEGEND RARE'][c.rarity];}
function stars(n){return '★'.repeat(n)+'<span class="dim-stars">'+'★'.repeat(5-n)+'</span>';}
function miniCard(c,locked=false){return `<div class="mini-card rarity-${c.rarity} ${c.ultra?'ultra':''} ${locked?'locked':''} ${!locked&&level26(c)===3?'kira26':''}" style="--card-color:${c.color};--foil-delay:${foilDelay261(c)}s">${!locked?urLayers261(c)+kiraLayers26(c):''}<div class="portrait">${portrait(c)}</div><div class="card-corner">${locked?'???':rarityName(c)}</div><div class="card-bottom">${!locked?awakeningBadge26(c):''}<div class="rarity">${locked?'?????':'★'.repeat(c.rarity)}</div><h3>${locked?'？？？':c.name}</h3><div class="card-count"><span>${locked?'未発見':c.role}</span><span>${locked?'':(c.awakeningLevel26!==undefined?label26(c):(save.cards[c.id]||0)+'/4')}</span></div></div></div>`;}
function fullCard(c){return `<article class="full-card rarity-${c.rarity} ${c.ultra?'ultra':''} ${c.rarity>=4?'rare':''} ${level26(c)===3?'kira26':''}" style="--card-color:${c.color};--foil-delay:${foilDelay261(c)}s">${urLayers261(c)}${kiraLayers26(c)}${awakeningBadge26(c)}${c.ultra?'<div class="ur-engraving242" aria-hidden="true"></div><div class="ur-foil242" aria-hidden="true"></div>':''}<div class="portrait">${portrait(c)}</div><div class="card-title"><div><span class="card-series">CHRONICLE / ${GAME_DATA.eras.find(e=>e.id===c.era).name}</span><h3>${c.name}</h3></div><span class="rarity">${c.ultra?'<b class="ur-name242">UR</b>':''}${'★'.repeat(c.rarity)}<small>${rarityName(c)}</small></span></div><div class="card-body"><div class="card-meta">${c.role}</div><p class="card-desc">${c.desc}</p><div class="stats">${['武力','知力','政治力','カリスマ'].map((s,i)=>`<span>${s}<b title="基本 ${c.stats[i]} → ${baseStat26(c,i)}">${stars(c.stats[i])}${level26(c)?`<small class="stat-bonus26"> ${baseStat26(c,i)}</small>`:''}</b></span>`).join('')}</div><div class="skill"><b>◆ ${c.skill}</b><p>${c.ability}</p></div><div class="keywords">${c.keys.map(k=>`<span>${k}</span>`).join('')}</div><p class="card-footnote">${c.cardKind==='heritage'?'文化遺産を表す創作能力。':'能力値は創作上の表現。'}★は入手難度です。<br>人物の偉さや史実上の客観的評価ではありません。</p></div></article>`;}
function renderHeroes(){$('#heroBack').innerHTML=miniCard(GAME_DATA.cards.find(c=>c.id==='ganjin'));$('#heroFront').innerHTML=miniCard(GAME_DATA.cards.find(c=>c.id==='shotoku_ur'));}
renderHeroes();
function openDialog(html,cls=''){modalReturnFocus=document.activeElement;$('#dialogBox').className='modal-box '+cls;$('#dialogBox').innerHTML=html;$('#dialog').classList.add('open');$('#dialogBox').scrollTop=0;setTimeout(()=>$('#dialogBox button')?.focus(),0);}
function closeDialog(){$('#dialog').classList.remove('open');$('#dialogBox').innerHTML='';if(modalReturnFocus?.isConnected)modalReturnFocus.focus({preventScroll:true});modalReturnFocus=null;lastTime=performance.now();}
function showScreen(id){currentScreen=id;$$('.screen').forEach(e=>e.classList.toggle('active',e.id===id));if(id!=='battle')audioSys.set('title');if(id==='title')renderHeroes();window.scrollTo(0,0);}
function showSelect(){showScreen('select');$('#eraGrid').innerHTML=GAME_DATA.eras.map((e,i)=>{let r=save.records[e.id]||{};return `<button class="era-card" data-era="${e.id}"><div class="era-art"><img src="${ART['bg_'+e.id]}" alt="${e.name}をイメージした風景"><span class="era-number">CHRONICLE 0${i+1}</span></div><div class="era-details"><h3>${e.name} <span style="float:right;font-size:22px;color:var(--gold)">→</span></h3><p>${e.subtitle}</p><div class="era-record"><span>最長防衛 ${formatTime(r.time||0)}</span><span>BEST ${fmt(r.score||0)}</span></div></div></button>`;}).join('');$$('[data-era]').forEach(b=>b.onclick=()=>intro(b.dataset.era));$('#futureGrid').innerHTML=GAME_DATA.future.map(n=>`<div class="future">${n}　？？？<small>COMING SOON</small></div>`).join('');$('#bestPanel').innerHTML='<span class="eyebrow">SURVIVAL RECORDS</span><br>'+GAME_DATA.eras.map(e=>{let r=save.records[e.id]||{};return e.name+'：最長 '+formatTime(r.time||0)+'　最大COMBO '+(r.combo??'—')+'　最高ボス正答率 '+(r.knowledge??'—')+'%　最高ROUND '+(r.round??'—');}).join('<br>');}
function showCatalog(){showScreen('catalog');renderCatalog();}
function renderCatalog(){$('#catalogTabs').innerHTML=GAME_DATA.eras.map(e=>{let a=GAME_DATA.cards.filter(c=>c.era===e.id);return `<button data-tab="${e.id}" class="${catalogEra===e.id?'active':''}">${e.name}　${a.filter(c=>save.cards[c.id]).length}/${a.length}</button>`;}).join('');$$('[data-tab]').forEach(b=>b.onclick=()=>{catalogEra=b.dataset.tab;renderCatalog();});$('#cardGrid').innerHTML=GAME_DATA.cards.filter(c=>c.era===catalogEra).map(c=>`<button class="card-slot" data-card="${c.id}" aria-label="${save.cards[c.id]?c.name+' '+save.cards[c.id]+'枚':'未獲得カード'}">${miniCard(c,!save.cards[c.id])}</button>`).join('');$$('[data-card]').forEach(b=>b.onclick=()=>{let c=GAME_DATA.cards.find(c=>c.id===b.dataset.card);openDialog(save.cards[c.id]?`<div class="card-view">${fullCard(c)}<div class="card-view-note"><div class="eyebrow">YOUR COLLECTION</div><h2>${c.name}</h2>${awakeningDetail26(c)}<p class="mini-note">イラストは史料の再現ではなく、人物や文化をもとにした創作です。</p>${c.legendNote?`<p class="mini-note">${c.legendNote}</p>`:''}<button id="useCard24" class="primary">このカードでバトルへ</button><button id="closeModal" class="ghost">図鑑へ戻る</button></div></div>`:'<h2>まだ見ぬ記憶</h2><p class="guide-text">タイピングで時空ポイントを集め、時空召喚で人物カードを手に入れよう。</p><div class="modal-actions"><button id="closeModal" class="primary">図鑑へ戻る</button></div>','card-view-box');$('#closeModal').onclick=closeDialog;if($('#useCard24'))$('#useCard24').onclick=()=>{closeDialog();selectedCard24=c.id;if(save.teamBattle27?.mode==='solo')save.teamBattle27.formations.solo=[c.id];showBattleSetup24();};});storageNotice();}
function intro(eraId){audioSys.start();let e=GAME_DATA.eras.find(e=>e.id===eraId);openDialog(`<div class="eyebrow">ENDLESS DEFENSE / SURVIVAL</div><h2>${e.name}を、何分守れる？</h2><div class="era-art"><img src="${ART['bg_'+eraId]}" alt="${e.name}"></div><div class="dialog-fact"><b>通常戦：</b>お題を見てローマ字入力。短い言葉の敵は速い！<br><b>ボス戦：</b>問いから答えを思い出して入力。3問正解で撃破。<br>ボスを倒すと、さらに敵が増える通常戦へ。ライフが尽きるまで続きます。</div><p class="mini-note">ボスはローマ字・日本語どちらも使えます。漢字変換した場合は、確定後もう一度Enterで攻撃。<br>通常戦は半角英字推奨。対応キーボードでは日本語入力ONでもキー位置で打てます。</p><div class="modal-actions"><button id="startBtn" class="primary">防衛開始</button><button id="cancelBtn" class="ghost">戻る</button></div>`);$('#startBtn').onclick=()=>{closeDialog();startGame(eraId);};$('#cancelBtn').onclick=closeDialog;}
function normalParams(round){return {quota:12+Math.min(24,(round-1)*4),cap:Math.min(8,3+round),interval:Math.max(.70,2.8*Math.pow(.87,round-1)),speed:Math.max(.27,Math.pow(.87,round-1))};}
function enemyDuration(q,round){const chars=tokenize(q.kana).map(t=>t[0]).join('').length;return Math.max(3.2,(6+chars*.65)*normalParams(round).speed);}
function startGame(eraId){audioSys.start();game={era:GAME_DATA.eras.find(e=>e.id===eraId),round:1,mode:'normal',hp:5,maxHP:5,score:0,combo:0,maxCombo:0,correctKeys:0,wrongKeys:0,typedTime:0,elapsed:0,kills:0,normalClears:0,bosses:0,bossAsked:0,bossCorrect:0,enemies:[],particles:[],beams:[],floating:[],paused:false,finished:false,target:null,enemyID:0,rewards:[],review:[],wordBag:[],bossBag:[],pendingN:0,transTime:0,roundHinted:false,feedbackUntil:0,flash:0,shake:0};composing=false;$('#answerInput').value='';showScreen('battle');beginNormal();}
function nextWord(){if(!game.wordBag.length){game.wordBag=shuffle(GAME_DATA.questions.filter(q=>q.era===game.era.id));if(game.round===1&&game.kills===0){const short=game.wordBag.filter(q=>q.kana.length<=6),long=game.wordBag.filter(q=>q.kana.length>6);game.wordBag=[...short,...long];}}let candidates=game.wordBag.filter(q=>!game.enemies.some(e=>e.q.id===q.id));let q=candidates[0]||game.wordBag[0];game.wordBag.splice(game.wordBag.indexOf(q),1);return q;}
function beginNormal(){game.mode='normal';game.params=normalParams(game.round);game.spawned=0;game.resolved=0;game.enemies=[];game.target=null;game.paused=false;game.transTime=0;game.transition=null;game.spawnIn=0;game.feedbackUntil=0;game.bossHits=0;game.boss=null;$('#arena').classList.remove('boss-arena');$('#answerInput').value='';$('#bossChoices').hidden=true;$('#bossHud').hidden=true;$('#hintBtn').hidden=true;$('#answerInput').hidden=true;$('#submitBtn').hidden=true;$('#roman').hidden=false;$('#imeBanner').hidden=true;audioSys.set(game.era.id);spawnEnemy();spawnEnemy(.06);game.spawnIn=game.params.interval;updateDock();updateHUD();toast('ROUND '+game.round+' / 防衛開始');$('#battle').focus({preventScroll:true});}
function spawnEnemy(initialDepth=0){if(game.spawned>=game.params.quota)return;let q=nextWord(),occupied=game.enemies.filter(e=>e.depth<.55).map(e=>e.lane),lanes=shuffle([0,1,2,3]).sort((a,b)=>occupied.includes(a)-occupied.includes(b)),lane=lanes[0];let duration=enemyDuration(q,game.round),e={id:++game.enemyID,q,lane,x:[.17,.39,.61,.83][lane],depth:initialDepth,age:duration*initialDepth,duration,typed:'',hit:0,phase:Math.random()*6.28};game.enemies.push(e);game.spawned++;if(!game.target)game.target=e;game.spawnIn=game.params.interval*(1-.20*game.spawned/game.params.quota);updateDock();}
function beginBoss(){game.mode='boss';game.enemies=[];game.target=null;game.bossHits=0;game.bossAttempts=0;game.paused=false;game.transTime=0;game.transition=null;game.bossHit=0;game.bossQueue=[];if(game.era.bossRounds?.[game.round-1]){game.bossQueue=game.era.bossRounds[game.round-1].map(term=>GAME_DATA.questions.find(q=>q.era===game.era.id&&q.term===term));}else if(game.round===1||game.round===2&&game.era.secondBoss){let all=GAME_DATA.questions.filter(q=>q.era===game.era.id),required=game.round===2?game.era.secondBoss:(game.era.firstBoss||(game.era.id==='heian'?['壇ノ浦の戦い','保元・平治の乱',shuffle(['かな文字','紫式部','国風文化'])[0]]:['北条政子','承久の乱','幕府']));game.bossQueue=required.map(t=>all.find(q=>q.term===t));}$('#arena').classList.add('boss-arena');$('#bossHud').hidden=false;$('#bossChoices').hidden=true;$('#bossHud .boss-name').textContent=game.era.boss;audioSys.set('boss');newBossQuestion();toast('BOSS / 三つの記憶を取り戻せ');}
function nextBossQuestion(){game.bossQueue=game.bossQueue.filter(q=>q&&q.bossEligible!==false);if(game.bossQueue.length)return game.bossQueue.shift();game.bossBag=game.bossBag.filter(q=>q&&q.bossEligible!==false);if(!game.bossBag.length)game.bossBag=shuffle(GAME_DATA.questions.filter(q=>q.era===game.era.id&&q.bossEligible!==false));return game.bossBag.shift();}
function newBossQuestion(){let base=nextBossQuestion(),variants=[base.question,...(base.questionVariants||[])],q={...base,question:variants[Math.floor(Math.random()*variants.length)]};game.boss={q,age:0,limit:Math.max(15,34-(game.round-1)*1.7),hinted:false,wrong:false,typed:'',answered:false};game.bossAsked++;game.bossAttempts++;game.feedbackUntil=0;$('#answerInput').value='';composing=false;compositionEndedAt=0;$('#hintBtn').textContent='ヒント';updateDock();updateHUD();}
function updateHUD(){if(!game)return;$('#waveLabel').textContent='ROUND '+String(game.round).padStart(2,'0')+' / '+(game.mode==='boss'?'BOSS':'TYPING');$('#stageName').textContent=game.era.name;$('#hp').textContent='♥'.repeat(Math.max(0,game.hp))+'♡'.repeat(game.maxHP-Math.max(0,game.hp));$('#score').textContent=fmt(game.score);$('#combo').textContent=game.combo;$('#clock').textContent=formatTime(game.elapsed);$('#enemyCount').textContent=game.mode==='boss'?'正解 '+game.bossHits+' / 3':'撃破 '+game.kills+'体 / 接近中 '+game.enemies.length+'体';$('#restoration').textContent='記憶復元 '+game.normalClears+' WAVE / ボス撃破 '+game.bosses;$('#progressBar i').style.width=(game.mode==='boss'?game.bossHits/3:game.resolved/game.params.quota)*100+'%';if(game.mode==='boss'){$('#bossHud .bar i').style.width=(1-game.bossHits/3)*100+'%';$('#bossTimer').textContent=game.boss?'残り '+Math.max(0,Math.ceil(game.boss.limit-game.boss.age))+'秒':'';}}
function updateDock(){if(!game)return;const boss=game.mode==='boss';$('#targetDock').classList.toggle('boss-dock',boss);$('#answerInput').hidden=!boss;$('#submitBtn').hidden=!boss;$('#bossChoices').hidden=true;$('#hintBtn').hidden=!boss;$('#roman').hidden=boss;$('#levelLabel').textContent=boss?'BOSS QUIZ / 歴史の問いから答えを思い出す':'TYPING WAVE / 見て打つ・連続防衛';$('#battleHelp').textContent=boss?'日本語・ひらがなでOK / 変換確定後、もう一度Enter / Esc：一時停止':'半角英字で入力 / 最初の文字で自動照準 / Tab：敵を切替 / Esc：一時停止';if(boss){let b=game.boss;if(!b)return;$('#prompt').textContent=game.round>=2&&game.bossHits%2===1?b.q.description:b.q.question;$('#bossChoices').innerHTML='';$('#answerInput').placeholder='答えを入力 → Enter';$('#feedback').className='feedback';$('#feedback').textContent=b.hinted?'ヒント：'+b.q.hint:'答えをローマ字で入力してEnter。日本語・ひらがなも使えます。';if(!game.paused&&!game.transTime)$('#answerInput').focus({preventScroll:true});}else{const e=game.target;$('#prompt').innerHTML=e?esc(e.q.display)+` <span class="reading">${e.q.kana}</span><span class="enemy-kind">${ENEMY_TYPES[e.q.enemy].name}</span>`:'次の忘却軍が接近中…';$('#roman').innerHTML=e?'<span class="typed">'+esc(e.typed)+'</span><span class="next-letters">'+esc(pathsFor(e.q,e.typed)?.rest||'')+'</span>':'';if(game.elapsed>=game.feedbackUntil){$('#feedback').className='feedback';$('#feedback').textContent=e?(e.duration<10?'⚡ すばやい敵！ 短い言葉をすばやく打とう。':'正しく打つたびに命中。打ち切ると撃破！'):'敵が増える前に、次の一打を。';}}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('show');void $('#toast').offsetWidth;$('#toast').classList.add('show');}
function addCombo(n){let prev=game.combo;game.combo+=n;game.maxCombo=Math.max(game.combo,game.maxCombo);if(Math.floor(prev/10)!==Math.floor(game.combo/10)){toast(game.combo>=30?'歴史無双！ '+game.combo:game.combo>=20?'歴史連撃！ '+game.combo:game.combo+' COMBO!');audioSys.sfx('combo');}}
function miss(){game.combo=0;game.wrongKeys++;audioSys.sfx('miss');game.shake=.14;updateHUD();}
function typeKey(ch){if(!game||game.mode!=='normal'||game.paused||game.finished||game.transTime)return;if(ch==='n'&&performance.now()<game.pendingN&&!game.target?.typed){game.pendingN=0;return;}game.pendingN=0;let e=game.target;if(!e||!e.typed){let matching=game.enemies.filter(t=>pathsFor(t.q,t.typed+ch)).sort((a,b)=>b.depth-a.depth)[0];if(matching)e=matching;}if(!e)return;game.target=e;let res=pathsFor(e.q,e.typed+ch);if(res){e.typed+=ch;game.correctKeys++;addCombo(1);game.score+=10+Math.min(25,Math.floor(game.combo/10)*2);e.hit=.14;game.beams.push({x:e.x,depth:e.depth,life:.13,strong:false});audioSys.sfx('hit',game.combo);if(res.complete)killEnemy(e);else updateDock();}else{miss();game.feedbackUntil=game.elapsed+1.2;$('#feedback').className='feedback bad';$('#feedback').textContent='ミス：'+ch.toUpperCase()+'　続きから打とう！';}updateHUD();}
function killEnemy(e){if(e.q.kana.endsWith('ん')&&e.typed.endsWith('n')&&!e.typed.endsWith('nn'))game.pendingN=performance.now()+350;game.score+=180+Math.round((1-e.depth)*150);game.kills++;game.resolved++;burst(e.x,e.depth,26);audioSys.sfx('kill');game.enemies=game.enemies.filter(x=>x!==e);game.target=game.enemies.sort((a,b)=>b.depth-a.depth)[0]||null;game.floating.push({text:'+ '+(180+Math.round((1-e.depth)*150)),x:e.x,depth:e.depth,life:1.0});if(game.enemies.length===0&&game.spawned<game.params.quota)game.spawnIn=Math.min(.25,game.spawnIn);if(game.resolved>=game.params.quota)normalComplete();else updateDock();}
function normalComplete(){game.normalClears++;game.enemies=[];game.target=null;game.score+=500;toast('WAVE CLEAR!　時空ポイントを獲得');audioSys.sfx('clear');game.transTime=2.0;game.transition=()=>beginBoss();$('#prompt').textContent='ボスが接近！ 次は歴史クイズ3問。';$('#roman').textContent='通常ROUND突破ボーナス ＋15 pt';$('#feedback').textContent='ポイントは防衛終了時にまとめて受け取れます。カードは時空召喚で手に入れよう。';updateHUD();}
function normalizeJP(s){return s.normalize('NFKC').replace(/[\s・･　。．!！?？]/g,'').replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));}
function isCorrectAnswer(q,s){let raw=s.trim();if(!raw)return false;const norm=normalizeJP(raw);if([q.term,q.kana,...q.aliases,...q.jpAliases].some(v=>normalizeJP(v)===norm))return true;const roman=normalizeRoman(raw);return /^[a-z'\-]+$/.test(roman)&&!!pathsFor(q,roman)?.complete;}
function submitAnswer(){if(!game||game.mode!=='boss'||game.paused||game.finished||game.transTime||composing||performance.now()-compositionEndedAt<180)return;let b=game.boss;if(!b||b.answered)return;let input=$('#answerInput').value.trim();if(!input)return;b.typed=input;if(isCorrectAnswer(b.q,input)){b.answered=true;game.bossHits++;if(!b.wrong&&!b.hinted)game.bossCorrect++;game.score+=b.hinted?650:b.wrong?1100:1800;addCombo(5);game.bossHit=.7;game.flash=.14;game.shake=.3;game.beams.push({x:.5,depth:.58,life:.55,strong:true});burst(.5,.50,70);audioSys.sfx('critical');toast('CRITICAL！');game.review.push({q:b.q.id,status:b.hinted?'ヒントで正解':b.wrong?'考え直して正解':'自力で正解'});$('#feedback').className='feedback good';$('#feedback').textContent=b.q.explain;$('#answerInput').blur();game.transTime=2.2;game.transition=()=>{if(game.bossHits>=3)bossComplete();else newBossQuestion();};updateHUD();}else{game.combo=0;b.wrong=true;audioSys.sfx('miss');game.shake=.15;game.feedbackUntil=game.elapsed+3;$('#feedback').className='feedback bad';$('#feedback').textContent='もう一度考えよう。誤字も確認してね。ライフはまだ減りません。';$('#answerInput').select();updateHUD();}}
function giveHint(){if(!game||game.mode!=='boss'||game.paused||game.transTime)return;let b=game.boss;b.hinted=true;$('#feedback').className='feedback';$('#feedback').textContent='ヒント：'+b.q.hint;$('#hintBtn').textContent='ヒント表示中';$('#answerInput').focus();}
function takeDamage(){game.hp--;game.combo=0;game.flash=.4;game.shake=.35;audioSys.sfx('damage');if(game.hp<=0){finish();return true;}updateHUD();return false;}
function reached(e){const blocked28=interceptArrival28();if(!blocked28&&takeDamage())return;game.resolved++;game.enemies=game.enemies.filter(x=>x!==e);game.target=game.enemies.sort((a,b)=>b.depth-a.depth)[0]||null;game.feedbackUntil=game.elapsed+1.7;$('#feedback').className='feedback bad';$('#feedback').textContent=blocked28?'防壁！ LIFEを守った。次の敵を止めよう。':'防衛線突破！ LIFE −1　次の敵を止めよう。';if(game.resolved>=game.params.quota)normalComplete();else updateDock();}
function bossTimeout(){let b=game.boss;if(b.answered)return;b.answered=true;game.review.push({q:b.q.id,status:'時間切れ'});if(takeDamage())return;$('#feedback').className='feedback bad';$('#feedback').textContent='時間切れ。答えは「'+b.q.term+'」。'+b.q.explain;$('#answerInput').blur();game.transTime=2.6;game.transition=()=>newBossQuestion();}
function bossComplete(){game.bosses++;game.hp=Math.min(game.maxHP,game.hp+1);game.score+=1500;audioSys.sfx('clear');toast('BOSS CLEAR!　LIFE ＋1');game.paused=false;game.transTime=1.4;game.transition=()=>{game.round++;beginNormal();};$('#prompt').textContent='ボス撃破！ 次のROUNDへ。';$('#roman').textContent='ボス撃破ボーナス ＋'+(60+15*(game.bosses-1))+' pt';$('#feedback').className='feedback good';$('#feedback').textContent='ライフ1回復。獲得ポイントは防衛終了時に精算します。';updateHUD();}
function metrics(){const accuracy=game.correctKeys+game.wrongKeys?Math.round(game.correctKeys/(game.correctKeys+game.wrongKeys)*100):0,knowledge=game.bossAsked?Math.round(game.bossCorrect/game.bossAsked*100):0,cpm=Math.round(game.correctKeys/Math.max(1,game.typedTime)*60),total=accuracy*.3+(game.bossAsked?knowledge:50)*.35+Math.min(100,game.elapsed/3)*.2+Math.min(100,cpm/1.4)*.15;return {accuracy,knowledge,cpm,rank:grade(total)};}
function finish(retired=false){if(!game||game.finished)return;game.finished=true;game.paused=true;game.enemies=[];game.transTime=0;let m=metrics(),old=save.records[game.era.id]||{},newBest=game.elapsed>(old.time||0);awardTimePoints(m,old);save.records[game.era.id]={time:Math.max(old.time||0,game.elapsed),score:Math.max(old.score||0,game.score),accuracy:Math.max(old.accuracy||0,m.accuracy),knowledge:Math.max(old.knowledge||0,m.knowledge),combo:Math.max(old.combo||0,game.maxCombo),round:Math.max(old.round||0,game.round),bosses:Math.max(old.bosses||0,game.bosses),plays:(old.plays||0)+1};persist();closeDialog();showScreen('result');audioSys.sfx(retired?'clear':'over');$('#resultEyebrow').textContent='SURVIVAL REPORT / '+(retired?'防衛終了':'防衛線突破');$('#resultTitle').textContent=game.era.name+'を '+formatTime(game.elapsed)+' 守り抜いた！';$('#totalRank').textContent=m.rank;$('#totalScore').textContent=fmt(game.score);$('#resultMessage').textContent='ROUND '+game.round+' / '+game.kills+'体撃破 / ボス '+game.bosses+'体撃破';$('#newBest').hidden=!newBest;$('#newBest').textContent='最長防衛記録を更新！';const rows=[['防衛時間',formatTime(game.elapsed),'一時停止・演出を除く',''],['タイピング速度',m.cpm,'打 / 分（通常戦）',grade(m.cpm,[140,95,55])],['正確性',m.accuracy,'通常戦の入力 %',grade(m.accuracy,[97,90,75])],['ボス正答率',game.bossAsked?m.knowledge:'—','% / 自力 '+game.bossCorrect+'問',game.bossAsked?grade(m.knowledge):'—'],['最大COMBO',game.maxCombo,'COMBO',grade(game.maxCombo,[80,45,20])],['ボス撃破',game.bosses,'体 / 到達 ROUND '+game.round,'']];$('#metrics').innerHTML=rows.map(([n,v,u,r])=>`<div class="metric"><label>${n}</label><strong>${v}</strong><small>${u}</small><em>${r}</em></div>`).join('');$('#resultCards').innerHTML='<span>タイピングの報酬は時空ポイント。カードは「時空召喚」で獲得できます。</span>';$('#reviewList').innerHTML=game.review.map(r=>{let q=GAME_DATA.questions.find(q=>q.id===r.q);return `<div class="review-item"><span class="pill">${r.status}</span>　<b>${q.term}</b><br>${q.explain}</div>`;}).join('');}
function pause(){if(!game||game.paused||game.finished||currentScreen!=='battle')return;game.paused=true;openDialog('<div class="eyebrow">TIME FROZEN</div><h2>ひと息ついて、次の一打。</h2><p class="guide-text">敵・ボスの制限時間・防衛時間は止まっています。</p><div class="modal-actions"><button id="resumeBtn" class="primary">防衛に戻る</button><button id="leaveBtn" class="ghost">記録を残して終了</button></div>');$('#resumeBtn').onclick=()=>{closeDialog();game.paused=false;if(game.mode==='boss'&&!game.transTime)$('#answerInput').focus();else $('#battle').focus();};$('#leaveBtn').onclick=()=>{closeDialog();finish(true);};}
const bgCanvas=$('#backdrop'),bg=bgCanvas.getContext('2d'),battleCanvas=$('#battleCanvas'),ctx=battleCanvas.getContext('2d');
const frameCanvas=document.createElement('canvas');frameCanvas.width=1280;frameCanvas.height=600;const fc=frameCanvas.getContext('2d');
function fitCanvas(c){let w=Math.round(c.clientWidth),h=Math.round(c.clientHeight),d=Math.min(devicePixelRatio||1,2);if(c.width!==w*d||c.height!==h*d){c.width=w*d;c.height=h*d;}return [w,h,d];}
function enemyPos(e){return {x:320+(e.x-.5)*640*(.62+e.depth*.52),y:150+e.depth*132,size:(ENEMY_TYPES[e.q?.enemy]?.size||66)*(.52+e.depth*.68)};}
function drawBackground(c,W,H,era,restore,t){const src=pixelAssets['bg_'+era]||(imageAssets['bg_'+era]?.complete?imageAssets['bg_'+era]:null);c.imageSmoothingEnabled=true;if(src&&src.width){const level=Math.round(restore*20);let cached=backgroundCache[era];if(!cached||cached.level!==level){let canvas=document.createElement('canvas');canvas.width=1280;canvas.height=Math.round(1280*src.height/src.width);let cc=canvas.getContext('2d');cc.filter='saturate('+(.35+restore*.65)+') brightness('+(.72+restore*.28)+')';cc.drawImage(src,0,0,canvas.width,canvas.height);cached=backgroundCache[era]={level,canvas};}let im=cached.canvas,scale=Math.max(W/im.width,H/im.height),w=im.width*scale,h=im.height*scale;c.drawImage(im,(W-w)/2,(H-h)/2,w,h);}else{c.fillStyle='#222a43';c.fillRect(0,0,W,H);}c.fillStyle='#0a12251c';c.fillRect(0,0,W,H);for(let i=0;i<16;i++){const x=(i*91+t*(era==='heian'?5:2))%(W+20)-10,y=(i*43+t*7)%(H+20)-10;c.fillStyle=era==='heian'?'#efb7ba99':era==='muromachi'?'#e0ce9866':'#89d8cd66';c.fillRect(Math.round(x),Math.round(y),2,1);}}
function drawSprite(e,t){let p=enemyPos(e),im=pixelAssets[e.q.enemy]||(imageAssets[e.q.enemy]?.complete?imageAssets[e.q.enemy]:null);const bob=e.q.enemy==='kemari'?Math.abs(Math.sin(t*7+e.phase))*7:Math.sin(t*3+e.phase)*3;fc.fillStyle='#060b19aa';fc.beginPath();fc.ellipse(Math.round(p.x),Math.round(p.y+2),p.size*.36,p.size*.085,0,0,Math.PI*2);fc.fill();if(im){fc.save();if(e.hit>0)fc.filter='brightness(2)';const size=p.size*1.45;fc.translate(Math.round(p.x),Math.round(p.y-p.size*.48-bob));if(e.q.enemy==='scroll'||e.q.enemy==='fan')fc.rotate(Math.sin(t*2+e.phase)*.06);fc.drawImage(im,-size/2,-size/2,size,size);fc.restore();}if(game.target===e){fc.strokeStyle='#ffdd8f';fc.lineWidth=1;let s=p.size*.63,x=Math.round(p.x),y=Math.round(p.y-p.size*.52-bob);for(const sx of [-1,1])for(const sy of [-1,1]){fc.beginPath();fc.moveTo(x+sx*s,y+sy*(s-7));fc.lineTo(x+sx*s,y+sy*s);fc.lineTo(x+sx*(s-7),y+sy*s);fc.stroke();}}}
function burst(x,depth,n){let p={x:320+(x-.5)*640*(.62+depth*.52),y:150+depth*132-30};if(game.mode==='boss')p={x:320,y:145};for(let i=0;i<n;i++)game.particles.push({x:p.x,y:p.y,vx:(Math.random()-.5)*210,vy:(Math.random()-.5)*180,life:.3+Math.random()*.4,color:i%3?'#ffdaa1':'#95f5df'});}
function renderEnemyLabels(){const container=$('#enemyLabels');if(game.mode==='boss'||game.transTime){if(container.childElementCount)container.innerHTML='';return;}const alive=new Set(game.enemies.map(e=>String(e.id)));[...container.children].forEach(el=>{if(!alive.has(el.dataset.id))el.remove();});let used=[];for(const e of [...game.enemies].sort((a,b)=>b.depth-a.depth)){let el=container.querySelector('[data-id="'+e.id+'"]');if(!el){el=document.createElement('div');el.className='enemy-label';el.dataset.id=e.id;el.addEventListener('pointerdown',ev=>{ev.preventDefault();if(game.mode==='normal'&&!game.paused){game.target=e;updateDock();$('#battle').focus();}});container.append(el);}let p=enemyPos(e),target=game.target===e;el.classList.toggle('target',target);const content='<b>'+esc(e.q.display)+'</b><small><span class="typed">'+esc(e.typed)+'</span>'+esc(pathsFor(e.q,e.typed)?.rest||'')+'</small>';if(el.dataset.content!==content){el.innerHTML=content;el.dataset.content=content;}let x=Math.max(.10,Math.min(.90,p.x/640)),y=Math.max(.08,(p.y-p.size*1.13)/300);const width=Math.min(.34,Math.max(.13,(e.q.kana.length*6+35)/640));for(let tries=0;tries<4;tries++){if(!used.some(a=>Math.abs(a.x-x)<(a.w+width)*.50&&Math.abs(a.y-y)<.14))break;y=Math.max(.055,y-.135);}used.push({x,y,w:width});el.style.left=x*100+'%';el.style.top=y*100+'%';el.style.zIndex=String(Math.floor(e.depth*10)+1);}}
function drawBattle(t,dt){const W=640,H=300;fc.setTransform(2,0,0,2,0,0);fc.clearRect(0,0,W,H);drawBackground(fc,W,H,game.era.id,Math.min(1,game.normalClears*.22),t);const shaking=game.shake>0;if(shaking){game.shake=Math.max(0,game.shake-dt);fc.save();fc.translate(Math.round((Math.random()-.5)*5),Math.round((Math.random()-.5)*3));}if(game.mode==='boss'){const im=pixelAssets['boss_'+game.era.id]||(imageAssets['boss_'+game.era.id]?.complete?imageAssets['boss_'+game.era.id]:null);fc.fillStyle='#070b2355';fc.fillRect(0,0,W,H);if(im){fc.save();if(game.bossHit>0)fc.filter='brightness('+(1+game.bossHit*2)+')';const size=230+Math.sin(t*2)*4;fc.drawImage(im,320-size/2,145-size/2+Math.sin(t*2)*3,size,size);fc.restore();}game.bossHit=Math.max(0,game.bossHit-dt);if(game.boss){const remaining=1-game.boss.age/game.boss.limit;fc.fillStyle='#151326';fc.fillRect(192,278,256,5);fc.fillStyle=remaining<.25?'#f490a2':'#ffcc7a';fc.fillRect(192,278,256*Math.max(0,remaining),5);}}else{[...game.enemies].sort((a,b)=>a.depth-b.depth).forEach(e=>drawSprite(e,t));fc.strokeStyle='#84efd399';fc.setLineDash([7,6]);fc.beginPath();fc.moveTo(0,291);fc.lineTo(640,291);fc.stroke();fc.setLineDash([]);}
for(const beam of game.beams){const pos=game.mode==='boss'?{x:320,y:151}:{x:320+(beam.x-.5)*640*(.62+beam.depth*.52),y:150+beam.depth*132-24};fc.save();fc.globalAlpha=Math.min(1,beam.life/(beam.strong?.45:.13));fc.strokeStyle=beam.strong?'#fff4c7':'#bdf4d8';fc.lineWidth=beam.strong?10:1+Math.min(4,game.combo/15);fc.beginPath();fc.moveTo(320,320);fc.lineTo(pos.x,pos.y);fc.stroke();if(beam.strong){fc.strokeStyle='#fff';fc.lineWidth=2;fc.beginPath();fc.moveTo(230,220);fc.lineTo(410,74);fc.stroke();}fc.restore();beam.life-=dt;}game.beams=game.beams.filter(b=>b.life>0);
for(const p of game.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=150*dt;p.life-=dt;fc.globalAlpha=Math.min(1,Math.max(0,p.life)*2);fc.fillStyle=p.color;fc.fillRect(Math.round(p.x),Math.round(p.y),2,2);}fc.globalAlpha=1;game.particles=game.particles.filter(p=>p.life>0);for(const f of game.floating){f.life-=dt;let p=enemyPos({x:f.x,depth:f.depth,q:{enemy:'scroll'}});fc.fillStyle='#ffe9a4';fc.font='bold 10px monospace';fc.textAlign='center';fc.fillText(f.text,p.x,p.y-55-(1-f.life)*15);}game.floating=game.floating.filter(f=>f.life>0);if(shaking)fc.restore();if(game.flash>0){fc.fillStyle=game.mode==='boss'?'#fff1b922':'#ff40582e';fc.fillRect(0,0,W,H);game.flash=Math.max(0,game.flash-dt);}let[w,h,d]=fitCanvas(battleCanvas);ctx.setTransform(d,0,0,d,0,0);ctx.imageSmoothingEnabled=true;ctx.drawImage(frameCanvas,0,0,w,h);renderEnemyLabels();}
function tick(dt){if(!game||game.finished||game.paused||currentScreen!=='battle')return;if(game.transTime>0){game.transTime=Math.max(0,game.transTime-dt);if(!game.transTime){let fn=game.transition;game.transition=null;fn?.();}return;}game.elapsed+=dt;const advanceDt28=stepStop28(dt);if(game.mode==='normal'){game.typedTime+=dt;game.spawnIn-=advanceDt28;for(const e of [...game.enemies]){e.age+=advanceDt28;e.depth=e.age/e.duration;e.hit=Math.max(0,e.hit-dt);if(e.depth>=1){reached(e);if(game.finished||game.transTime)break;}}if(game.finished||game.transTime)return;if(advanceDt28>0&&game.spawnIn<=0&&game.enemies.length<game.params.cap&&game.spawned<game.params.quota)spawnEnemy();}else{let b=game.boss;if(!b||b.answered)return;b.age+=advanceDt28;if(b.age>b.limit*.65&&!b.hinted){b.hinted=true;$('#hintBtn').textContent='ヒント表示中';$('#feedback').className='feedback';$('#feedback').textContent='ヒント：'+b.q.hint;}if(b.age>=b.limit)bossTimeout();}updateHUD();}
function loop(now){let dt=Math.min(.10,(now-lastTime)/1000);lastTime=now;visualTime+=dt;if(document.hidden||$('#dialog').classList.contains('open')){requestAnimationFrame(loop);return;}if(currentScreen==='battle'&&game){tick(dt);drawBattle(visualTime,game.paused?0:dt);}else{let[w,h,d]=fitCanvas(bgCanvas);bg.setTransform(d,0,0,d,0,0);drawBackground(bg,w,h,currentScreen==='catalog'?catalogEra:'asuka_nara',.75,visualTime);}requestAnimationFrame(loop);}requestAnimationFrame(loop);
function showGuide(){const resume=currentScreen==='battle'&&game&&!game.finished&&!game.paused;if(resume)game.paused=true;openDialog(`<div class="eyebrow">SURVIVAL FIELD GUIDE / VERSION 2.8</div><h2>何分間、歴史を守れる？</h2><div class="guide-text"><h3>飛鳥・奈良編が開幕（v2.5）</h3><p>国づくり、税と人々の負担、仏教、大陸との交流の36語・16枚を追加。平安・室町にも「京都」を追加しました。全4編・124語・46枚で遊べます。</p><p>飛鳥・奈良の最初のボスは聖徳太子→遣隋使→大化の改新。次は平城京→租→大仏、3回目は庸→調→律令、4回目は防人→鑑真→正倉院。以降は「雑徭」を除く問題から出題します。「雑徭」は通常タイピングだけに登場します。</p><p>「雑徭」は「ぞうよう」、「隋」は「ずい」です。「十七条憲法」は「じゅうしちじょうけんぽう」「じゅうななじょうけんぽう」の両方を受け付けます。聖徳太子の通常版とUR版は同じ人物。中大兄皇子と天智天皇も同一人物の即位前・即位後です。大仏は人物ではない文化遺産カードです。</p><h3>通常戦 → ボス戦 → さらに激しい通常戦</h3><p>難易度選択はありません。通常戦で迫る忘却軍を倒し、ボス戦で歴史クイズに3問正解すると、次のROUNDへ進みます。ROUNDが進むほど敵の数・同時出現数・接近速度が上がります。ライフがなくなるまで防衛時間を伸ばそう。</p><h3>通常戦：見てタイピング</h3><p>敵の上のお題を、ローマ字で入力。正しい一打ごとに攻撃し、最後まで打つと撃破。短い言葉の敵ほど速く、長い言葉の敵は遅めです。最初の文字で敵を自動選択します。<kbd>Tab</kbd>や敵のラベルをクリックして変更もできます。ミスしても、入力した部分は消えません。</p><p>半角英字での入力を推奨します。Chrome系の物理キーボードでは、日本語入力がONでもキー位置で判定します。IMEの動作は端末ごとに違うため、うまく打てない場合は「半角／全角」や「英数」で英字に切り替えてください。</p><h3>ボス戦：問いから答えを思い出す</h3><p>問いや説明を読んで、答えの歴史用語を入力します。答えは表示されません。ローマ字で入力してEnterで攻撃できます。<b>日本語入力・漢字変換に対応</b>。例：<b>源義経</b>。ひらがな「みなもとのよしつね」でもOKです。<b>変換を確定するEnterのあと、もう一度Enter</b>で攻撃します。「答えを確定」ボタンでも攻撃できます。</p><p>3問正解でボス撃破。誤答しても即ダメージにはなりません。制限時間が過ぎるとライフ−1で、正解の解説を見て次の問題へ。ヒントも使えます。日本語入力中もボスの制限時間は進みます。</p><h3>操作</h3><table><tr><th>通常戦</th><td>英字 / スペース不要 / 大文字もOK</td></tr><tr><th>ボス戦</th><td>ローマ字で入力 → Enter / 日本語も可</td></tr><tr><th>一時停止</th><td>Esc / 一時停止ボタン</td></tr><tr><th>音</th><td>右上の音 ON/OFF</td></tr></table><p>shi/si、chi/ti、tsu/tu、fu/hu、ji/zi、sha/syaなどに対応。「ん」はn/nn（母音・y・nの前はnnまたはn'）。ボスはローマ字の答えも受け付けますが、日本語でそのまま入力できます。</p><h3>音楽と文化問題（v2.1）</h3><p>タイトル・平安・鎌倉・室町・ボスに、それぞれ旋律と伴奏のある専用曲を用意しました。琴・笛・太鼓などをイメージした合成音です。右上の音楽室で試聴・BGM音量の調節ができます。音は最初のクリックから鳴ります。</p><p>平安は32語。かな文字・ひらがな・和歌・十二単・寝殿造・大和絵・絵巻物・藤原頼通を追加しました。文字と文学、人物と作品のつながりも出題します。</p><h3>人物・歴史拡張（v2.2）</h3><p>保元の乱・平治の乱・壇ノ浦の戦いを追加。平安の最初のボスでは「壇ノ浦の戦い」と「保元・平治の乱」が必ず出題されます。鎌倉末期と世界とのつながりも追加し、平安・鎌倉は計58語になりました。</p><p>カードは平安10人・鎌倉11人。弁慶は★★★★★の特別枠「ULTRA RARE」。時空召喚の通常召喚で低確率で出現し、UR確定召喚では${GAME_DATA.cards.filter(c=>c.ultra).length}枚のURのいずれかを獲得できます。現在は★★★★★全${GAME_DATA.cards.filter(c=>c.ultra).length}枚をURとして扱いますが、人物の偉さを示すものではありません。弁慶の紹介・能力には伝説に基づく表現があります。</p><h3>室町時代が開幕（v2.3）</h3><p>室町28語・9枚のカードを追加。当時の3時代で86語・30枚になりました。室町の最初のボスは金閣→銀閣→応仁の乱、次のボスは書院造→水墨画→能。以降は室町の全問題から出題します。</p><p>金閣と北山文化、銀閣と東山文化、今の和室や芸能とのつながりを思い出そう。「生花」は生け花（いけばな）として出題します。若い信長・光秀は創作したヤング版。尊氏は鎌倉版と室町版を別々に集められます。</p><h3>ポイント・召喚・回復</h3><p>タイピングの報酬は時空ポイントです。通常ROUND突破・ボス撃破・COMBO・正確性・歴史問題への正答でポイントが増え、防衛終了時に受け取れます。カードの新規獲得は時空召喚だけ。ボス撃破時のライフ1回復は続きます。すでに集めたカードや所持枚数はそのまま使えます。</p><h3>防衛時間・成績・保存</h3><p>防衛時間は実際に戦っている時間。一時停止、ROUND間の演出、正解解説などの合間は含めません。通常戦とボス戦の戦闘中は進みます。生存時間の自己ベストは時代ごとに保存します。総合評価は正確性30%、ボスの歴史知識35%、防衛時間20%、入力速度15%です。</p><p>ボス正答率は、ヒント・誤答なしで正解した問題数÷出題数。時間切れや途中終了の未解答問題も分母に含めます。通常戦の正確性とは別に集計します。</p><p>記録は同じブラウザのlocalStorageに保存されます。個人名は不要です。図鑑からバックアップ・読み込みができます。旧版の人物カードも引き継げます。ファイルの名前や場所が変わって記録が出ない場合は、旧版で書き出した記録を読み込んでください。</p><h3>時空召喚・カードバトル（v2.4）</h3><p>タイピングの終了時に時空ポイントを獲得。通常ROUND突破、正確性、自力で答えた歴史問題、ボス連続撃破にも報酬があります。ライフが尽きても、メニューの「記録を残して終了」でも、その回の獲得分が保存されます。何も倒さずに終了した場合は0 ptです。</p><p>通常召喚300 pt・UR確定召喚5,000 pt。通常召喚のUR率は0.5%。★★★★★は全${GAME_DATA.cards.filter(c=>c.ultra).length}枚をURとして扱います。召喚画面にレアリティ別の排出率を表示します。ポイントの購入や課金はありません。</p><p>集めたカードで1vs1・2vs2・3vs3のCPU戦。★上限は5・8・12。先鋒から順に出場し、負けた側だけ交代。勝者の残りHPはそのままです。「強攻」「守備」「鼓舞」を選んでサイコロを振ります。人物に応じた出目で特殊能力が発動。攻撃は同時で、両チームが同時に全滅した場合は引き分けです。カードは消費しません。勝利のたびに1vs1で100 pt、2vs2で150 pt、3vs3で200 pt。さらに20%・30%・40%で支援チケット1枚を獲得します。敗北・引き分けは0 pt。旧版の報酬枠制限はありません。</p><p>v2.4は別の保存領域を使い、初回は同じブラウザにあるv2.3の記録を引き継ぎます。v2.3の保存領域には書き込みません。別ファイルや別の端末で記録が見つからない場合は、v2.3の図鑑でバックアップし、v2.4の図鑑で読み込んでください。読み込み時に既存カードの枚数を減らすことはありません。</p><h3>レアリティ再編（v2.6.1）</h3><p>全46枚を★1：13枚、★2：13枚、★3：11枚、★4：5枚、UR：4枚に再編。URは聖徳太子UR・武蔵坊弁慶・源頼朝・足利義満。★は人物の偉さではなく、収集上の希少性です。v2.7では★数がチームの編成コストになります。覚醒・キラMAXでも★数は変わりません。</p><p>人物IDと所持・覚醒はそのまま。これまでの時空のかけらは減りません。これからのMAX後重複は新しい★に従って変換します。URは希少性、キラMAXは育て切った証。それぞれ別の装飾が重なります。</p><h3>覚醒とキラカード（v2.6）</h3><p>1枚目は通常、2枚目は覚醒Ⅰ（基本能力＋2%）、3枚目は覚醒Ⅱ（＋4%）、4枚目はキラMAX（＋6%）。★・UR・特殊能力・HPは変わりません。5枚目以降は時空のかけらになります。★1・★2は1個、★3は2個、★4は3個、URは5個。交換所ではハート＋1・時止め5秒が3個、防壁が4個で交換できます。</p><p>旧版の所持枚数を引き継ぎ、4枚を超えた分は一度だけかけらへ変換します。累計獲得枚数も記録されます。同じ人物の別カード（通常・URや時代違い）は別々に覚醒します。</p><h3>時空防衛への支援（v2.8）</h3><p>時代を選んだ後、1プレイに1種類・1枚だけ選べます。「使わない」も選べます。ハート＋1は開始時に消費し、その回のライフと上限が＋1。時止めは戦闘中のボタンで発動し、敵の接近・新出現とボスの制限時間を5秒止めます。入力は続けられ、一時停止や解説中は5秒を減らしません。防壁は敵の防衛線到達ダメージを1回無効化します。ボスの時間切れには使いません。</p><p>時止め・防壁は発動した時だけ消費し、未使用なら残ります。アイテムを使ってもスコア・自己ベスト・ポイントは通常どおり保存します。図鑑・召喚画面の交換所から、時空のかけらをチケットに交換できます。</p><h3>先生へ</h3><p>ゲーム本体はこのHTMLだけで動作します。画像・音・コードはすべて内蔵。Chrome・Edgeなどで、ダウンロードしたファイルを開いてください。学校端末の設定によってローカルHTMLの実行が制限される場合があります。</p><p>人物画、敵、背景は創作イラストです。服飾・建築・合戦の史料再現ではありません。敵は歴史の記憶を奪う「忘却軍」で、歴史上の人物を倒す設定ではありません。★は入手難度。能力値と特殊能力は人物の特徴を表す創作で、史実上の客観的評価ではありません。v2.4ではカードバトルに能力を利用します。</p><details><summary>出題の確認先</summary><p>飛鳥・奈良編：<a href="https://horyuji.or.jp/garan/" target="_blank" rel="noopener">法隆寺</a> ／ <a href="https://www.todaiji.or.jp/history/narajidai/" target="_blank" rel="noopener">東大寺</a> ／ <a href="https://www.toshodaiji.jp/ganjin.html" target="_blank" rel="noopener">唐招提寺・鑑真</a> ／ <a href="https://www.heijo-park.jp/about/heijokyo/" target="_blank" rel="noopener">平城宮跡歴史公園</a> ／ <a href="https://www.kunaicho.go.jp/kids/shisetsu/shosoin.html" target="_blank" rel="noopener">宮内庁きっず・正倉院</a></p><p><a href="https://jpsearch.go.jp/gallery/ndl-G7gBQ4dOBYQ" target="_blank" rel="noopener">ジャパンサーチ：上代〜中世の文学</a><br><a href="https://www.rekihaku.ac.jp/assets/pdf/learning/stuff/kaisetsu_heian.pdf" target="_blank" rel="noopener">国立歴史民俗博物館：平安貴族の暮らし</a></p><p><a href="https://www.city.kamakura.kanagawa.jp/rekibun/hojo3.html" target="_blank" rel="noopener">鎌倉市：北条義時とその時代</a></p><p>リンクは資料確認用です。ゲーム中の通信はありません。システムの着想参考：ひなテックGames「ゾンビタイピング」。参考作品のコード・画像・音楽は使用していません。</p></details></div><div class="close-row"><button id="closeGuide" class="primary">${resume?'防衛に戻る':'閉じる'}</button></div>`);$('#closeGuide').onclick=()=>{closeDialog();if(resume){game.paused=false;if(game.mode==='boss')$('#answerInput').focus();}};}
$('#selectBtn').onclick=()=>{audioSys.start();showSelect();};$('#catalogBtn').onclick=()=>{audioSys.start();showCatalog();};$$('[data-home]').forEach(b=>b.onclick=()=>showScreen('title'));$('#brandHome').onclick=()=>{if($('#dialog').classList.contains('open'))return;if(currentScreen==='battle'){pause();return;}showScreen('title');};$('#guideBtn').onclick=()=>{if(!$('#dialog').classList.contains('open'))showGuide();};$('#muteBtn').onclick=()=>audioSys.toggle();$('#pauseBtn').onclick=pause;$('#hintBtn').onclick=giveHint;$('#submitBtn').onclick=submitAnswer;$('#retryBtn').onclick=()=>startGame(game.era.id);$('#nextEraBtn').onclick=showSelect;$('#resultCatalogBtn').onclick=()=>{catalogEra=game.era.id;showCatalog();};
const input=$('#answerInput');input.addEventListener('compositionstart',()=>{composing=true;});input.addEventListener('compositionend',()=>{composing=false;compositionEndedAt=performance.now();if(game?.boss)game.boss.typed=input.value;});input.addEventListener('input',()=>{if(game?.mode==='boss')game.boss.typed=input.value;});
document.addEventListener('keydown',ev=>{if(ev.ctrlKey||ev.metaKey||ev.altKey)return;if($('#dialog').classList.contains('open')){if(ev.key==='Tab'){const els=$$('#dialogBox button:not(:disabled),#dialogBox a,#dialogBox input');if(!els.length)return;let i=els.indexOf(document.activeElement);if(ev.shiftKey&&i<=0){ev.preventDefault();els.at(-1).focus();}else if(!ev.shiftKey&&i===els.length-1){ev.preventDefault();els[0].focus();}}if(ev.key==='Escape')($('#resumeBtn')||$('#closeMusic')||$('#closeGuide')||$('#closeModal')||$('#cancelBtn'))?.click();return;}if(currentScreen==='title'&&ev.key==='Enter'&&(!ev.target.closest?.('button')||ev.target.id==='selectBtn')){ev.preventDefault();audioSys.start();showSelect();return;}if(currentScreen!=='battle'||!game||game.finished)return;if(ev.key==='Escape'){if(composing)return;ev.preventDefault();pause();return;}if(game.paused||game.transTime)return;if(game.mode==='normal'){if(ev.key==='Tab'){ev.preventDefault();let n=game.enemies.length,i=game.enemies.indexOf(game.target);game.target=game.enemies[(i+1)%n]||null;updateDock();return;}if(ev.key==='Backspace'||ev.key===' '){ev.preventDefault();return;}let ch=/^Key[A-Z]$/.test(ev.code)?ev.code.slice(3).toLowerCase():/^[a-zA-Z'\-]$/.test(ev.key)?ev.key.toLowerCase():null;if(ch){ev.preventDefault();$('#imeBanner').hidden=true;typeKey(ch);}else if(ev.keyCode===229&&!ev.code){$('#imeBanner').hidden=false;$('#imeBanner').textContent='このキーボードでは「半角／全角」か「英数」で英字に切り替えてください。';}}else{if(ev.isComposing||ev.keyCode===229||composing)return;if(ev.key==='Enter'){ev.preventDefault();submitAnswer();}else if(document.activeElement!==input&&!['Tab','Shift','Control','Alt','Meta'].includes(ev.key)){input.focus();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&currentScreen==='battle'&&game&&!game.paused)pause();});window.addEventListener('blur',()=>{if(currentScreen==='battle'&&game&&!game.paused&&!composing)pause();});
$('#exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='chronicle-survival-record-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#saveStatus').textContent='記録をダウンロードしました。端末を替えるときは、このファイルを読み込んでください。';};
$('#importBtn').onclick=()=>$('#importFile').click();$('#importFile').onchange=async ev=>{let file=ev.target.files[0];if(!file)return;try{if(file.size>1e6)throw Error('ファイルが大きすぎます。');let imported=validSave(JSON.parse(await file.text()));openDialog('<h2>記録を読み込みますか？</h2><p class="guide-text">現在の記録を、選んだバックアップに置き換えます。旧版の記録では人物カードを引き継ぎます。必要なら先に現在の記録をバックアップしてください。</p><div class="modal-actions"><button id="confirmImport" class="primary">読み込む</button><button id="cancelImport" class="ghost">やめる</button></div>');$('#confirmImport').onclick=()=>{save=imported;persist();renderMute();audioSys.musicLevel=.30*save.settings.musicVolume/100;audioSys.applyMute();closeDialog();renderCatalog();$('#saveStatus').textContent='記録を読み込みました。';};$('#cancelImport').onclick=closeDialog;}catch(err){$('#saveStatus').textContent='読み込めませんでした。'+err.message;}ev.target.value='';};

function showMusicRoom(){
 if($('#dialog').classList.contains('open'))return;
 const previous=audioSys.track,resume=currentScreen==='battle'&&game&&!game.finished&&!game.paused;
 if(resume)game.paused=true;
 audioSys.audition=true;audioSys.start();
 openDialog(`<div class="eyebrow">SOUND GALLERY / v2.5</div><h2>時空の音楽室</h2><p class="guide-text">曲を選んで試聴。戦闘中に開いた場合、敵と時間は止まります。</p><div class="music-tracks">${Object.entries(MUSIC_TRACKS).map(([id,tr])=>`<button data-track="${id}" class="ghost"><small>${{title:'タイトル',asuka_nara:'飛鳥・奈良時代',heian:'平安時代',kamakura:'鎌倉時代',muromachi:'室町時代',boss:'ボス戦'}[id]}</small><b>▶ ${tr.name}</b><span>${{title:'光が広がるベルと弦のテーマ',asuka_nara:'鐘と笛風の響き、古代の都のテーマ',heian:'琴・笛風の音色と軽やかな伴奏',kamakura:'太鼓と弦のリズムで前へ',muromachi:'笛と琴風の音がつなぐ、金と墨の都',boss:'速いビートと緊迫した旋律'}[id]}</span></button>`).join('')}</div><label class="music-volume" for="musicVolume">BGM音量 <output id="volumeValue">${save.settings.musicVolume}%</output><input id="musicVolume" type="range" min="0" max="100" value="${save.settings.musicVolume}"></label><p class="mini-note">オリジナルの合成音楽です。歴史上の音楽の再現ではありません。効果音の音量は変わりません。</p><div class="close-row"><button id="closeMusic" class="primary">${resume?'防衛に戻る':'閉じる'}</button></div>`);
 const mark=()=>$$('[data-track]').forEach(b=>b.classList.toggle('active',b.dataset.track===audioSys.track));mark();
 $$('[data-track]').forEach(b=>b.onclick=()=>{if(save.settings.mute)audioSys.toggle();audioSys.set(b.dataset.track);mark();});
 $('#musicVolume').oninput=ev=>{save.settings.musicVolume=Number(ev.target.value);audioSys.musicLevel=.30*save.settings.musicVolume/100;if(audioSys.musicBus&&!audioSys.suspendedMusic)audioSys.musicBus.gain.setTargetAtTime(audioSys.musicLevel,audioSys.ctx.currentTime,.02);$('#volumeValue').textContent=save.settings.musicVolume+'%';};
 $('#musicVolume').onchange=persist;
 $('#closeMusic').onclick=()=>{audioSys.audition=false;audioSys.set(previous);closeDialog();if(resume){game.paused=false;if(game.mode==='boss')$('#answerInput').focus();else $('#battle').focus();}};
}
$('#musicBtn').onclick=showMusicRoom;
